// 16.9.0 — npm pack stays under 14 MB unpacked without raising the limit (check:pack failed at 14.04 MB on the 16.9
// bump: +53 KB, of which ~20 KB were two bundled copies of the Scene v3 types for the deprecated scene/v3-preview
// entry). Genuine cuts: (1) scene-v3-preview.d.ts / .d.cts become a re-export of scene-v3 (same API; generated by
// scripts/alias-dts.mjs after the build); (2) GitHub-only pages leave the tarball: docs/compare/ (16.9), the 10.9 audit
// report and the upgrade guides for majors 3–9 (their codemods left in 15.0). npm renders README links to them from
// the repository. Limit unchanged (scripts/check-pack.mjs PACK_LIMITS).
import { describe, it, expect } from 'vitest';
import { readFileSync, mkdtempSync, mkdirSync, writeFileSync, existsSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const ROOT = join(__dirname, '..');
const pkg = JSON.parse(readFileSync(join(ROOT, 'package.json'), 'utf8'));

describe('16.9 npm pack cuts', () => {
  it('GitHub-only pages are excluded from the tarball; the limit is unchanged', async () => {
    for (const x of ['!docs/compare', '!docs/audit-10.9.md', '!docs/upgrading-[3-9].md']) expect(pkg.files).toContain(x);
    const src = readFileSync(join(ROOT, 'scripts/check-pack.mjs'), 'utf8');
    expect(src).toContain('unpacked: 14 * 1024 * 1024');
  });
  it('scripts/alias-dts.mjs writes scene-v3-preview declarations as a re-export of scene-v3 (and runs in the build)', async () => {
    expect(pkg.scripts.build).toContain('node scripts/alias-dts.mjs');
    const { run } = await import('../scripts/alias-dts.mjs');
    const d = mkdtempSync(join(tmpdir(), 'alias-dts-'));
    mkdirSync(join(d, 'components'));
    expect(run(d)).toBe(0); // no scene-v3-preview.js → nothing to do (17.0 removes the entry)
    writeFileSync(join(d, 'components/scene-v3-preview.js'), '');
    expect(run(d)).toBe(2);
    const ts = readFileSync(join(d, 'components/scene-v3-preview.d.ts'), 'utf8');
    const cts = readFileSync(join(d, 'components/scene-v3-preview.d.cts'), 'utf8');
    expect(ts).toContain("export * from './scene-v3.js';");
    expect(cts).toContain("export * from './scene-v3.cjs';");
    expect(ts).toContain('@deprecated');
    expect(ts.length).toBeLessThan(1000);
    expect(existsSync(join(d, 'components/scene-v3-preview.d.cts'))).toBe(true);
  });
});
